#include "bits/stdc++.h"

using namespace std;

using ll = long long;

void solve () {
    int n, k;
    cin >> n >> k;
    vector<ll> pref(n + 1);
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        pref[i + 1] = pref[i] + a[i];
    }
    map<ll, vector<int>> pos;
    for (int i = 0; i <= n; i++) {
        pos[pref[i]].push_back(i);
    }
    auto get = [&] (int l, int r, ll want) {
        if (l > r) return 0;
        auto it = std::lower_bound(pos[want].begin(), pos[want].end(), l) - pos[want].begin();
        auto it2 = std::upper_bound(pos[want].begin(), pos[want].end(), r) - pos[want].begin();
        return int(it2 - it);
    };
    int ans = 0;
    for (int s = 0; s < n; s++) {
        ll want = pref[s];
        int res = 0;
        res += get(s + 1, n, want);
//        for (int i = s + 1; i <= n; i++) res += pref[i] == want;
        want = -pref[n] + pref[s];
        res += get(1, s, want);
//        for (int i = 1; i <= s; i++) res += pref[i] == want;
        ans += res == k;
    }
    cout << ans << '\n';
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);
    cout.tie(0);
    int t = 1;
    cin >> t;
    while (t--) {
        solve();
    }
}
